(* [comment removed for export] *)
Lemma know_ok_unhide : forall E (H1 H2 : word -> bool) FULL k,
  H_off_segments SEGS H1 ->
  kimg_in_hull k ->
  (forall a, H2 a = true -> H1 a = true) ->
