(* [comment removed for export] *)
Lemma maps_match_rekind : forall E ms l (f : amap -> amap),
  (forall m, am_base (f m) = am_base m /\ am_len (f m) = am_len m /\ is_fog (f m) = is_fog m) ->
  maps_match E ms l -> maps_match E (map f ms) l.
