Lemma fact_sound : forall E cs R FULL model K,
  cs_ok E cs R FULL model -> fact_ok (kn cs) K = true -> cs_ok E (add_kn cs [K]) R FULL model.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S60!1+^P!1,^O|600;|30;!3,B+cQ#3!1,M+cQ!1'bU#7!4'bQ#8#7#4#5!6'c[#8#7#6#5#4#2$E;R+^[$cs;R+_:$R;R!2'^N!1,^O|21;0$FULL;R%~R0!1+^Q!1+^P!1,^O1$model;R+^R$K;R+cQ$HC;R!5+a=#6#5#4#3#2$H;R!3+:+^;!2'mJ!1'bU#6#2,^<vd!8'cY#8#7#6#5#4!3'_<+cQ23#2!6,fT+cQ!3'cR/SEGS;#84#33!6'mR#843#35#15!5+a=#8!2'mS#72#6#5#4").
Qed.

Lemma regs_ok_ext_eq : forall E sr sr' R, sr = sr' -> regs_ok E sr R -> regs_ok E sr' R.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10!1+N+_6$E;R+^[$sr;R0$sr';R0$R;R!2'^N!1,^O|21;!1+^P!1,^O|600;$~R!3+:0#3#2$~R!3'bL#5#4#2!7'^B0#4$sr;R0%H0;R!3'bL#7#1#4!3'bL#8#6#5$H0;R!3'bL#6#4#3#1#5#2#1").
Qed.

(* [comment removed for export] *)
