Lemma kn_bigsubst_sound : forall K k nx E2 M,
  know_ok SEGS E2 M k -> APK.kn_vars_lt nx k = true ->
  (forall i, (i < length (kn_bigexprs K k))%nat -> ev E2 (nx + i) = edenot E2 (nth i (kn_bigexprs K k) (ELit 0))) ->
