Lemma A_bytes_fm_split : forall E (f : expr * expr -> bool) l,
  A_bytes (flat_map (allow1 E) l)
  = A_bytes (flat_map (allow1 E) (List.filter f l)) + A_bytes (flat_map (allow1 E) (List.filter (fun p => negb (f p)) l)).
