Section RenameCS.
  Variable m : list (nat * nat).
  Variables fw bw : list (option nat).
  Hypothesis Hfw : mk_fwd m = Some fw.
  Hypothesis Hbw : mk_bwd m = Some bw.
  Variable gb : nat.
  Hypothesis Hgb : (nx0 <= gb)%nat.
  Hypothesis Hm : forallb (fun p => Nat.leb gb (fst p) && Nat.leb gb (snd p)) m = true.

  Let ER := edenot_rename m fw bw Hfw Hbw.

  Lemma ren_agree : forall E, env_agree gb E (ren_env bw E).
  Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "SN0!2'k1#1/gb;!1+^P!1,^O|600;!3+:1!2'k2#3#2!2'k2!2'^_:/bw;#3#2|30;%~R+_Z!1+N!1+^P!1,^O3!1'`@!2'^_:/bw;#1!2'^^Z/bw;#2!1+^Q+_Z!2'k2#7#6!2+_5+_Z+_Z%~R!3+:7!2'^^Z/bw;#1!2,`>+_Z#2!3'`G9!4,_@+_Z+_Z#3#2/m;$p;R9!2'^H!2'eH/gb;!3'_8+_Z+_Z#1!2'eH/gb;!3'_9+_Z+_Z#1!3+:+^;!3'iE9;/m;,^<%x;R9%~R!3'`G9#1/m;!3+:+^;!1;#2,^<!4,_@+_Z+_Z#4#9!2'eH/gb;#5!2'eH/gb;#:!3+:+^;!2'eH/gb;#6,^<%~R!3+:+^;!2'eH#2#1,^<!2+dN#3#2!1'`3/gb;!1'`3#A!2'6CD!2,^:+0C!1'`3#B!2'=GC!1+S+0|10;!2,^2+0J!2,^2+0,J!1,\+U$E;R+^[!4,`L%n;R+_Z%~R02!3+:4!1'`@#15$n;R+_Z$Hn;R0vd&o;R67&Eb;R!2,^:7#1!3+:7!2'^^Z/bw;#3#1!1-^QRN$o;R!1+^Q+_Z%Eb;R!3+:7!2'^^Z/bw;#5#1!3+:18-^QRN$x;R!1+^Q+_Z1#22$s;R+_Z!2'k2#8#18#22$n;R+_Z!1$s;R+_Z$Eb;R!3+:7!2'^^Z/bw;#6!2,`>+_Z#1&H;R$s;R+_Z$d;R+_Z!5'_P:%~R!3'`G9!4,_@+_Z+_Z#2#1/m;!3+:76!2,`>+_Z#3%~R!3+:7!2'^^Z/bw;#1!2,`>+_Z#2!3'`G9!4,_@+_Z+_Z#3#2/m;$~R:$~R%~R!3'`G9!4,_@+_Z+_Z#3#2/m;!3+:7!2'^^Z/bw;#3!2,`>+_Z#4#2!5'^_;/m;/bw;/Hbw;#2#1%s;R+_Z%d;R+_Z:&Eb;R!3#1#3#8#2!3'`G9!4,_@+_Z+_Z#3#8/m;!2'`T!3+:1!2'k2#:#9!2'k2#:#4&X;R!6'`I%~R<=%~R=<!3'jV9;/m;/Hm;>#1!3+:+^;!1;>,^<&X;R!3'a9?@#1!2+>!3+:+^;?,^<!3+:+^;@,^<!5'_PA!3+:+^;!2'eH/gb;#;,^<+^?$~RA$~R!3+:+^;!2'eH/gb;#<,^<!2$_H;R!3+:+^;!2'eH/gb;#8,^<$X;R!3+:+^;!2'eH/gb;#>,^<&H;R$n;R+_Z$m;R+_Z!5'_PB%~R!2+dN#2#1!3+:+^;!2'eH#3#2,^<%~R!3+:+^;!2'eH#2#1,^<!2+dN#3#2$~RB$~R%~R!2+dN#3#2!3+:+^;!2'eH#4#3,^<#2!2'eJ#2#1%n;R+_Z%m;R+_ZB&X;R!3#1/gb;#@#2!2+dN/gb;#@&X0;R!4'dR!2+dN/gb;#AE!<'dS+_Z+0+dN'`3'6'dT/gb;CF#AD!2,^:+0D#1E&Hn0;R!4'dR!2'k1#B/gb;H!<'dS+_Z+0'k1'`3'='k6#BG!2,^:+0G/gb;CF#AH&cstr;R!1'dG#C!2'6,7!1'`3#C&cstr0;R!1'dG/gb;!2'6,7C&__arith;R$__p1;Rw$__x2;R+0$__x1;R+0&__wit;R!1,M+C!1+N+C&__varmap;R!4,O+0!2,P+0#3#2!1,^D+0!1+Q+0&__ff;R!8,RI'T+U+U,V!7,WI'T+U+U,V!4,X+0K,ZL,[M!8,RI'T+U+U,V!7,WI'T+U+U,V!4,X+0L,^1K,[M!6,^3I'T+U+U,V#5!2'^8I,V!4'^9#1#3vv!2,^:+^;,^<!3+:+^;!2'^=#1#3,^<!3'^>+0,7#2%__p1;Rw%__x2;R+0%__x1;R+0%~R!2'=#2#1%~R!2'6#2#3#5!5#1+^?!1'`3#FC#4#5#2#1#1#1$Eb;R!3+:7!2'^^Z/bw;#4!1,\+_Z!2,^:1!2'k2#6#5#12!2,^:45").
Qed.

  Lemma uE_rename : forall E e, evars_all (ren_ok fw bw) e = true -> uE (ren_env bw E) (erename fw e) = uE E e.
  Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S50!1,^O|600;!1+^P0!2'_A#3#2!2'^_:/bw;#3!2'^_7/fw;#2$E;R+^[$e;R+_6$~R!3+:+^;!2'^_4!2'^_</fw;/bw;#1,^<vd!6'^B12$b;R1!3+:+0!2'`K0#1!2'`K0!2'_A#4#3!2,^:+0!2'`K02!2'_A34!3/ER;#3#2#1!3+:+0!2'_734!2'_7#3#2").
