Definition lc_guard (lc : option loopctx) (cs : acs) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$lc;R!1+^Q+tI$cs;R+_:-^QRN$lc;R!1+^Q+tI+^;#22$c;R+tI!2'eH!1'tK#1!1'g:#2,^<").

